"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_mathematics_en"]=window.LC_CHUNKS["university_mathematics_en"]||{};window.LC_CHUNKS["university_mathematics_en"][10]={"university_mathematics_en:M10-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M10-L1 – Mathematical literature, proof reading and seminars<\/h1>\n<p><strong>Course area:<\/strong> M10 – Seminar and research<\/p>\n<p><strong>Level:<\/strong> Bachelor’s studies · Seminar<\/p>\n<p><strong>Prerequisites:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L1&amp;syslang=en&amp;doclang=en&amp;theme=light\">M1-L1<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L2&amp;syslang=en&amp;doclang=en&amp;theme=light\">M1-L2<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L3&amp;syslang=en&amp;doclang=en&amp;theme=light\">M1-L3<\/a><\/p>\n<p><strong>Classification:<\/strong> Bachelor seminar pathway<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Learning objectives<\/h2>\n<p>Reconstruct the dependencies of a mathematical proof, distinguish\nassumptions from conclusions, find counterexamples to stronger claims,\nand prepare an original seminar write-up with documented sources.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Formulating a literature question<\/h2>\n<p>A seminar paper starts not with a collection of formulas but with a\nverifiable question: why is continuity preserved by uniform limits but\nnot by pointwise limits? Choose an interval\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo>⊆<\/mo><mi mathvariant=\"double-struck\">ℝ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">I\\subseteq\\mathbb R<\/annotation><\/semantics><\/math>\nand real-valued functions\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo>:<\/mo><mi>I<\/mi><mo>→<\/mo><mi mathvariant=\"double-struck\">ℝ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f_n:I\\to\\mathbb R<\/annotation><\/semantics><\/math>.\nThe basic concepts appear in <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L2&amp;syslang=en&amp;doclang=en&amp;theme=light\">M1-L2<\/a> and <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L3&amp;syslang=en&amp;doclang=en&amp;theme=light\">M1-L3<\/a>. For each source record\nthe author or institution, title, edition, precise location and access\ndate. Describe the role of each assertion in your own words: definition,\nestablished lemma, main theorem or mere example. Matching formulations\nin two texts do not constitute an independent proof. When assumptions\ndiffer, first check whether the statements are actually equivalent.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Reconstructing the proof<\/h2>\n<p><strong>Theorem.<\/strong> If all\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>f<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">f_n<\/annotation><\/semantics><\/math>\nare continuous on\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>I<\/mi><annotation encoding=\"application/x-tex\">I<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>f<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">f_n<\/annotation><\/semantics><\/math>\nconverges uniformly to\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>:<\/mo><mi>I<\/mi><mo>→<\/mo><mi mathvariant=\"double-struck\">ℝ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f:I\\to\\mathbb R<\/annotation><\/semantics><\/math>,\nthen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nis continuous on\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>I<\/mi><annotation encoding=\"application/x-tex\">I<\/annotation><\/semantics><\/math>.<\/p>\n<p><strong>Proof.<\/strong> Choose any\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>∈<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x_0\\in I<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ε<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon&gt;0<\/annotation><\/semantics><\/math>.\nBy uniform convergence choose one index\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nsuch that\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mi>ε<\/mi><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|f_n(x)-f(x)|&lt;\\varepsilon/3<\/annotation><\/semantics><\/math>\nfor all\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>∈<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x\\in I<\/annotation><\/semantics><\/math>.\nSince this fixed\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>f<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">f_n<\/annotation><\/semantics><\/math>\nis continuous at\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">x_0<\/annotation><\/semantics><\/math>,\nthere exists\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>δ<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\delta&gt;0<\/annotation><\/semantics><\/math>\nsuch that\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mi>ε<\/mi><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|f_n(x)-f_n(x_0)|&lt;\\varepsilon/3<\/annotation><\/semantics><\/math>\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>∈<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x\\in I<\/annotation><\/semantics><\/math>\nwith\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>x<\/mi><mo>−<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mi>δ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|x-x_0|&lt;\\delta<\/annotation><\/semantics><\/math>.\nThe triangle inequality gives<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>+<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>+<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mi>ε<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|f(x)-f(x_0)|\\le |f(x)-f_n(x)|+|f_n(x)-f_n(x_0)|+|f_n(x_0)-f(x_0)|&lt;\\varepsilon.<\/annotation><\/semantics><\/math><\/p>\n<p>Thus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nis continuous at\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">x_0<\/annotation><\/semantics><\/math>.\nBecause\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">x_0<\/annotation><\/semantics><\/math>\nwas arbitrary, it is continuous throughout\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>I<\/mi><annotation encoding=\"application/x-tex\">I<\/annotation><\/semantics><\/math>.\nThe proof does not require compactness of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>I<\/mi><annotation encoding=\"application/x-tex\">I<\/annotation><\/semantics><\/math>;\nat endpoints use relative continuity. The order of choosing\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>δ<\/mi><annotation encoding=\"application/x-tex\">\\delta<\/annotation><\/semantics><\/math>\nmatters. A proof dependency graph records the definition of uniform\nconvergence, continuity of the fixed term, and the triangle inequality\nas separate inputs.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-en/media/img/U_MAT_045_EN.svg\"\nalt=\"Proof graph from convergence and continuity to error bound\" />\n<figcaption aria-hidden=\"true\">Proof graph from convergence and\ncontinuity to error bound<\/figcaption>\n<\/figure>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Testing hypotheses with counterexamples<\/h2>\n<p>Replacing uniform convergence with pointwise convergence makes the\ntheorem false. Choose\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>x<\/mi><mi>n<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f_n(x)=x^n<\/annotation><\/semantics><\/math>\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">x\\in[0,1]<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>≥<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n\\ge1<\/annotation><\/semantics><\/math>.\nEvery term is continuous; the limit is zero for\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x&lt;1<\/annotation><\/semantics><\/math>\nand one at\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x=1<\/annotation><\/semantics><\/math>.\nIt is therefore discontinuous at one. For every fixed\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi mathvariant=\"normal\">sup<\/mi><mo>&#8289;<\/mo><\/mrow><mrow><mi>x<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>f<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sup_{x\\in[0,1]}|f_n(x)-f(x)|=1<\/annotation><\/semantics><\/math>,\nalthough this error is not attained: approaching one from the left,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mi>n<\/mi><\/msup><annotation encoding=\"application/x-tex\">x^n<\/annotation><\/semantics><\/math>\ntends to one, while at one the error is zero. On\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,a]<\/annotation><\/semantics><\/math>\nwith\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>a<\/mi><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0&lt;a&lt;1<\/annotation><\/semantics><\/math>,\nby contrast, the maximum error is\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>a<\/mi><mi>n<\/mi><\/msup><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a^n\\to0<\/annotation><\/semantics><\/math>.\nThis tests the role of the domain using the same example. The supremum\nargument establishes the claim; an additional self-produced plot can\nillustrate the boundary region.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Seminar workflow and evidence<\/h2>\n<p>Prepare a two- to three-page seminar write-up containing the\nquestion, definitions, theorem, proof, counterexample and limitations.\nMark every external assertion you do not prove with a precise reference.\nDistinguish notes taken from sources from your own argument. For the\nexample above, reconstruct the proof without a template and then check\nthe order of choices against the definitions. Oxford’s guidance on\ncounterexamples and Stanford’s proofwriting checklist provide\nmethodological references; the proof and examples above are\nindependently developed here.<\/p>\n<p>Allow about ten minutes for the presentation: two for concepts, four\nfor the proof, three for the counterexample and one for limitations. Ask\na second reader to trace the dependencies backwards, especially where\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nis chosen independently of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>.\nDuring self-study, revisiting the proof later may help but does not\nreplace independent review. Label unresolved questions as such.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-assessment<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">State the quantifier order of uniform convergence.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Why is pointwise convergence insufficient for the proof?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Find an integer\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nfor which the error of\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>x<\/mi><mi>n<\/mi><\/msup><annotation encoding=\"application/x-tex\">x^n<\/annotation><\/semantics><\/math>\non\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1/2]<\/annotation><\/semantics><\/math>\nis less than\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/100<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Give a counterexample showing that uniform convergence alone does\nnot guarantee continuity if the terms are not continuous.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Outline a proof dependency graph and source record for the\ntheorem.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Show solutions<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">For every\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ε<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon&gt;0<\/annotation><\/semantics><\/math>\nthere exists\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nsuch that for every\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>≥<\/mo><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n\\ge N<\/annotation><\/semantics><\/math>\nand every\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x<\/mi><mo>∈<\/mo><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x\\in I<\/annotation><\/semantics><\/math>\nthe error is smaller than\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ε<\/mi><annotation encoding=\"application/x-tex\">\\varepsilon<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">The required index could depend on\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>;\ncontinuity of a single fixed term would no longer control the errors\ntogether.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=7<\/annotation><\/semantics><\/math>\nsuffices since\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>2<\/mn><mrow><mi>−<\/mi><mn>7<\/mn><\/mrow><\/msup><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>128<\/mn><mo>&lt;<\/mo><mn>1<\/mn><mi>/<\/mi><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2^{-7}=1/128&lt;1/100<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Let each\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>f<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">f_n<\/annotation><\/semantics><\/math>\nbe the same step function\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mn>1<\/mn><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mi>∞<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msub><annotation encoding=\"application/x-tex\">1_{[0,\\infty)}<\/annotation><\/semantics><\/math>\non\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"double-struck\">ℝ<\/mi><annotation encoding=\"application/x-tex\">\\mathbb R<\/annotation><\/semantics><\/math>.\nThe error is identically zero, but the limit is discontinuous at\nzero.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Uniform convergence gives two error bounds, continuity the middle\none, and the triangle inequality combines them. Source record:\ninstitution, title, URL, section, date, assertion used and own\nverification; methodological references in S7.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://courses.maths.ox.ac.uk/mod/page/view.php?id=65664\">University\nof Oxford, Introduction to University Mathematics (2025–26): Logic and\nProof<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Counterexamples · Last accessed: 2026-11-24 · Content\nverified: 2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://web.stanford.edu/class/cs103/proofwriting_checklist\">Stanford\nUniversity, CS103 Proofwriting Checklist<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Clearly articulate\nassumptions; scope variables · Last accessed: 2026-11-24 · Content\nverified: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_en:M10-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M10-L2 – Mathematical research project and reproducibility<\/h1>\n<p><strong>Course area:<\/strong> M10 – Seminar and research<\/p>\n<p><strong>Level:<\/strong> Master’s studies · Research project<\/p>\n<p><strong>Prerequisites:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M10&amp;lesson=L1&amp;syslang=en&amp;doclang=en&amp;theme=light\">M10-L1<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M7&amp;lesson=L3&amp;syslang=en&amp;doclang=en&amp;theme=light\">M7-L3<\/a><\/p>\n<p><strong>Classification:<\/strong> Master’s research pathway<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Learning objectives<\/h2>\n<p>Formulate a bounded research question and testable hypothesis,\ndistinguish analytical proof from numerical experiment, document code,\ninputs and results, and explain why negative or unevaluable findings\nmust be retained.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Research question and predefined test plan<\/h2>\n<p>Build on <a href=\"index.html?course=university_mathematics&amp;module=M10&amp;lesson=L1&amp;syslang=en&amp;doclang=en&amp;theme=light\">M10-L1<\/a> and <a\nhref=\"index.html?course=university_mathematics&amp;module=M7&amp;lesson=L3&amp;syslang=en&amp;doclang=en&amp;theme=light\">M7-L3<\/a>. Ask how the endpoint\nerror of Euler and explicit midpoint methods changes when the step size\nis halved for\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mi>′<\/mi><mo>=<\/mo><mn>3<\/mn><msup><mi>t<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y\\prime=3t^2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(0)=0<\/annotation><\/semantics><\/math>\non\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>.\nThe exact solution\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>t<\/mi><mn>3<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y(t)=t^3<\/annotation><\/semantics><\/math>\nprovides an independent reference. For\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nuniform steps,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">h=1/n<\/annotation><\/semantics><\/math>.\nBefore computing, define absolute endpoint error\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo>−<\/mo><msub><mi>y<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E_n=|1-y_n|<\/annotation><\/semantics><\/math>\nand observed order\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mi>/<\/mi><msub><mi>E<\/mi><mrow><mn>2<\/mn><mi>n<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">p_n=\\log_2(E_n/E_{2n})<\/annotation><\/semantics><\/math>\nwhen both errors are positive. Hypothesis:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>p<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">p_n<\/annotation><\/semantics><\/math>\napproaches one for Euler and two for midpoint. Choose\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>8<\/mn><mo>,<\/mo><mn>16<\/mn><mo>,<\/mo><mn>32<\/mn><mo>,<\/mo><mn>64<\/mn><mo>,<\/mo><mn>128<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=8,16,32,64,128<\/annotation><\/semantics><\/math>\nand their doubles for the finite test plan. All five pairs should\nsatisfy\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>p<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mn>0.05<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|p_n-1|&lt;0.05<\/annotation><\/semantics><\/math>\nfor Euler and\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>p<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mn>0.05<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|p_n-2|&lt;0.05<\/annotation><\/semantics><\/math>\nfor midpoint. These tolerances are a predefined choice for this teaching\nproject, not a general statistical test. Also test\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mi>′<\/mi><mo>=<\/mo><mn>2<\/mn><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y\\prime=2t<\/annotation><\/semantics><\/math>\nwith the same initial condition as a control. Record any changes to the\nplan rather than adapting it retrospectively to the data.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Analytical proof for the test problem<\/h2>\n<p>The right-hand side depends only on\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>t<\/mi><annotation encoding=\"application/x-tex\">t<\/annotation><\/semantics><\/math>.\nEuler therefore corresponds to the left rectangle sum, and explicit\nmidpoint to midpoint quadrature. With\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>j<\/mi><\/msub><mo>=<\/mo><mi>j<\/mi><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_j=j/n<\/annotation><\/semantics><\/math>,<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>y<\/mi><mi>n<\/mi><mi>E<\/mi><\/msubsup><mo>=<\/mo><mfrac><mn>3<\/mn><msup><mi>n<\/mi><mn>3<\/mn><\/msup><\/mfrac><munderover><mo>∑<\/mo><mrow><mi>j<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><mrow><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/munderover><msup><mi>j<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>1<\/mn><mo>−<\/mo><mfrac><mn>3<\/mn><mrow><mn>2<\/mn><mi>n<\/mi><\/mrow><\/mfrac><mo>+<\/mo><mfrac><mn>1<\/mn><mrow><mn>2<\/mn><msup><mi>n<\/mi><mn>2<\/mn><\/msup><\/mrow><\/mfrac><mo>,<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y_n^{E}=\\frac{3}{n^3}\\sum_{j=0}^{n-1}j^2=1-\\frac{3}{2n}+\\frac{1}{2n^2},<\/annotation><\/semantics><\/math><\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>y<\/mi><mi>n<\/mi><mi>M<\/mi><\/msubsup><mo>=<\/mo><mfrac><mn>3<\/mn><msup><mi>n<\/mi><mn>3<\/mn><\/msup><\/mfrac><munderover><mo>∑<\/mo><mrow><mi>j<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><mrow><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/munderover><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mn>1<\/mn><mo>−<\/mo><mfrac><mn>1<\/mn><mrow><mn>4<\/mn><msup><mi>n<\/mi><mn>2<\/mn><\/msup><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y_n^{M}=\\frac{3}{n^3}\\sum_{j=0}^{n-1}(j+1/2)^2=1-\\frac{1}{4n^2}.<\/annotation><\/semantics><\/math><\/p>\n<p>The first equation follows from\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑<\/mo><msup><mi>j<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sum j^2=n(n-1)(2n-1)/6<\/annotation><\/semantics><\/math>.\nFor the second expand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><msup><mi>j<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(j+1/2)^2=j^2+j+1/4<\/annotation><\/semantics><\/math>\nand use\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑<\/mo><mi>j<\/mi><mo>=<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sum j=n(n-1)/2<\/annotation><\/semantics><\/math>.\nThus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>E<\/mi><mi>n<\/mi><mi>E<\/mi><\/msubsup><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><msup><mi>n<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E_n^{E}=3/(2n)-1/(2n^2)<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>E<\/mi><mi>n<\/mi><mi>M<\/mi><\/msubsup><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><msup><mi>n<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E_n^{M}=1/(4n^2)<\/annotation><\/semantics><\/math>.\nThe limiting error ratios are 2 and 4 respectively; the midpoint ratio\nis exactly 4. This proves the orders for this test problem, not for\nevery differential equation. General method analysis needs further\nregularity and stability assumptions.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Reproducible experiment<\/h2>\n<p>The following original script requires only Python and its standard\nlibrary. Save it as <code>experiment.py<\/code>, record the output of\n<code>python --version<\/code>, and run\n<code>python experiment.py<\/code>. Rational arithmetic keeps endpoint\nerrors exact; only the logarithmic display uses floating-point\narithmetic. <code>None<\/code> means the order cannot be evaluated, not\nthat it is zero.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> fractions <span class=\"im\">import<\/span> Fraction <span class=\"im\">as<\/span> F<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> math <span class=\"im\">import<\/span> log2<\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> error(n, degree, midpoint<span class=\"op\">=<\/span><span class=\"va\">False<\/span>):<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> <span class=\"bu\">type<\/span>(n) <span class=\"kw\">is<\/span> <span class=\"kw\">not<\/span> <span class=\"bu\">int<\/span> <span class=\"kw\">or<\/span> n <span class=\"op\">&lt;<\/span> <span class=\"dv\">1<\/span> <span class=\"kw\">or<\/span> degree <span class=\"kw\">not<\/span> <span class=\"kw\">in<\/span> (<span class=\"dv\">2<\/span>, <span class=\"dv\">3<\/span>):<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;positive integer n; degree 2 or 3&quot;<\/span>)<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    h <span class=\"op\">=<\/span> F(<span class=\"dv\">1<\/span>, n)<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    offset <span class=\"op\">=<\/span> F(<span class=\"dv\">1<\/span>, <span class=\"dv\">2<\/span>) <span class=\"cf\">if<\/span> midpoint <span class=\"cf\">else<\/span> F(<span class=\"dv\">0<\/span>)<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    y <span class=\"op\">=<\/span> h <span class=\"op\">*<\/span> <span class=\"bu\">sum<\/span>(degree <span class=\"op\">*<\/span> ((j <span class=\"op\">+<\/span> offset)<span class=\"op\">*<\/span>h)<span class=\"op\">**<\/span>(degree<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>)<\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                <span class=\"cf\">for<\/span> j <span class=\"kw\">in<\/span> <span class=\"bu\">range<\/span>(n))<\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> <span class=\"bu\">abs<\/span>(<span class=\"dv\">1<\/span><span class=\"op\">-<\/span>y)<\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> observed_order(e, refined):<\/span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> e <span class=\"op\">&lt;=<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">or<\/span> refined <span class=\"op\">&lt;=<\/span> <span class=\"dv\">0<\/span>:<\/span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">return<\/span> <span class=\"va\">None<\/span><\/span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> log2(<span class=\"bu\">float<\/span>(e <span class=\"op\">/<\/span> refined))<\/span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">for<\/span> n <span class=\"kw\">in<\/span> (<span class=\"dv\">8<\/span>, <span class=\"dv\">16<\/span>, <span class=\"dv\">32<\/span>, <span class=\"dv\">64<\/span>, <span class=\"dv\">128<\/span>):<\/span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">for<\/span> midpoint <span class=\"kw\">in<\/span> (<span class=\"va\">False<\/span>, <span class=\"va\">True<\/span>):<\/span>\n<span id=\"cb1-20\"><a href=\"#cb1-20\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        e <span class=\"op\">=<\/span> error(n, <span class=\"dv\">3<\/span>, midpoint)<\/span>\n<span id=\"cb1-21\"><a href=\"#cb1-21\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"bu\">print<\/span>(n, midpoint, e,<\/span>\n<span id=\"cb1-22\"><a href=\"#cb1-22\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>              observed_order(e, error(<span class=\"dv\">2<\/span><span class=\"op\">*<\/span>n, <span class=\"dv\">3<\/span>, midpoint)))<\/span>\n<span id=\"cb1-23\"><a href=\"#cb1-23\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"bu\">print<\/span>(<span class=\"st\">&quot;control&quot;<\/span>, error(<span class=\"dv\">8<\/span>, <span class=\"dv\">2<\/span>, <span class=\"va\">True<\/span>))<\/span><\/code><\/pre><\/div>\n<p>For\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>E<\/mi><mn>8<\/mn><mi>E<\/mi><\/msubsup><mo>=<\/mo><mn>23<\/mn><mi>/<\/mi><mn>128<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E_8^E=23/128<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>E<\/mi><mn>8<\/mn><mi>M<\/mi><\/msubsup><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>256<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E_8^M=1/256<\/annotation><\/semantics><\/math>;\nfor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>16<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=16<\/annotation><\/semantics><\/math>,\nthey are\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>47<\/mn><mi>/<\/mi><mn>512<\/mn><\/mrow><annotation encoding=\"application/x-tex\">47/512<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>1024<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/1024<\/annotation><\/semantics><\/math>.\nHence\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>p<\/mi><mn>8<\/mn><mi>E<\/mi><\/msubsup><mo>=<\/mo><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>92<\/mn><mi>/<\/mi><mn>47<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><mn>0.969<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p_8^E=\\log_2(92/47)\\approx0.969<\/annotation><\/semantics><\/math>\nand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>p<\/mi><mn>8<\/mn><mi>M<\/mi><\/msubsup><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p_8^M=2<\/annotation><\/semantics><\/math>.\nThe graph shows error curves from the proven formulas. Check the script\noutput against them. For the same number of steps, the general midpoint\nmethod uses two function evaluations per step, versus one for Euler; in\nthis special time-dependent case both need only one. A runtime study\nwould need to measure cost and accuracy separately.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-en/media/img/U_MAT_046_EN.svg\"\nalt=\"Logarithmic error comparison of Euler and midpoint methods\" />\n<figcaption aria-hidden=\"true\">Logarithmic error comparison of Euler and\nmidpoint methods<\/figcaption>\n<\/figure>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Negative findings and research artifacts<\/h2>\n<p>For\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mi>′<\/mi><mo>=<\/mo><mn>2<\/mn><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y\\prime=2t<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(0)=0<\/annotation><\/semantics><\/math>,\nthe midpoint rule integrates the linear function exactly. Both errors in\nthe ratio are zero, so the observed order is undefined. Report this\nresult rather than replacing it with an artificial small number. It\nrefutes the unrestricted assertion that order can be measured in every\ntest case, not theoretical order two. A sequence of small errors also\ndoes not prove stability on stiff problems.<\/p>\n<p>Create a project directory with <code>README.md<\/code> (question,\nassumptions, versions, launch command), <code>experiment.py<\/code>,\nunaltered <code>results.txt<\/code>, a description of the output columns,\na proof note and a results report. Record SHA-256 for the versioned\nfiles; a hash confirms identity, not correctness. Record each change\nwith its reason and version. ACM SIGIR artifact review provides\nmethodological guidance: a rerun by the same person is not independent\nreproduction. Ask another person to obtain the results using the\nsupplied files; a separate reimplementation additionally tests\ndependence on the code. Report discrepancies with environment and\ninputs. This small project is a self-study example and claims neither\nscientific novelty nor certification.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Self-assessment<\/h2>\n<h3 id=\"exercises\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exercises<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Determine both errors for\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=4<\/annotation><\/semantics><\/math>\nexactly.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Calculate the midpoint error ratio when\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\ndoubles and its observed order.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Explain why no logarithmic error ratio exists for the control\nproblem.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">What claim about stiff differential equations cannot be established\nby the experiment?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Outline a minimal reproduction protocol for a second person.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Show solutions<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Euler:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>11<\/mn><mi>/<\/mi><mn>32<\/mn><\/mrow><annotation encoding=\"application/x-tex\">11/32<\/annotation><\/semantics><\/math>;\nmidpoint:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>64<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/64<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Ratio\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>4<\/mn><annotation encoding=\"application/x-tex\">4<\/annotation><\/semantics><\/math>,\norder\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msub><mn>4<\/mn><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\log_2 4=2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Both errors are zero;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mi>/<\/mi><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0/0<\/annotation><\/semantics><\/math>\nand its logarithm are undefined.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">The experiment establishes neither absolute stability for large\nnegative eigenvalues nor convergence for arbitrary stiff problems.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Check version and hashes, record Python version, run the command,\ncompare exact fractions and zero-error control, record discrepancies\nwith inputs and environment, and assess the result independently.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Sources<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://sigir.org/general-information/acm-sigir-artifact-badging/\">ACM\nSIGIR, Artifact Badging<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Artifact Packaging; Results Reproduced and\nReplicated · Last accessed: 2026-11-24 · Content verified:\n2026-11-24<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://gustavdelius.github.io/NumericalAnalysis2024/nmODE.html\">Gustav\nDelius, Numerical Analysis, Chapter 6<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (external link)<\/span><\/a> · Definition 6.2; Exercise\n6.23 · Last accessed: 2026-11-24 · Content verified: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>"};
